import os
import re


def slugify(text):
    s = text.strip().lower()
    s = re.sub(r"[^a-z0-9]", "-", s)
    return s.strip("-")


def title_case(text):
    words = text.split(" ")
    out = []
    for w in words:
        out.append(w[:1].upper() + w[1:].lower())
    return " ".join(out)


def initials(text):
    words = text.split(" ")
    out = []
    for w in words:
        out.append(w[:1].upper())
    return "".join(out)

